import math

def _q_sign_axis(q):
    # q in 0..7  -> (sign, axis)  where axis 0:1,1:i,2:j,3:k ; sign in {1,-1}
    sign = 1 if q % 2 == 0 else -1
    axis = q//2  # 0,1,2,3
    return sign, axis

def _q_mul(a, b):
    sa, ax = _q_sign_axis(a)
    sb, bx = _q_sign_axis(b)
    sign = sa * sb
    if ax == 0:
        axis = bx
    elif bx == 0:
        axis = ax
    elif ax == bx:
        axis = 0
        sign *= -1
    else:
        # cyclic ordering i(1)->j(2)->k(3)->i
        order = (1, 2, 3, 1)
        idx = order.index(ax)
        if order[idx+1] == bx:
            axis = order[idx+2]
        else:
            axis = order[idx]
            sign *= -1
    return axis*2 + (0 if sign==1 else 1)

def _q_inv(a):
    sign, axis = _q_sign_axis(a)
    return axis*2 + (0 if sign==1 else 1) if axis==0 else axis*2 + (0 if sign==-1 else 1)

def op(a, b, n):
    # Conjugation  a^{-1} * b * a  in quaternion group, n must be 8
    if n != 8:
        raise ValueError('This magma is defined only for n=8')
    ainv = _q_inv(a)
    return _q_mul(_q_mul(ainv, b), a)
